113	/**
114	 * Accepting runs unauthenticated: the token is the credential, so there is no
115	 * `Actor` to scope against and every check has to come off the stored row.
116	 */
117	export async function acceptInvitation(
118	  userId: UserId,
119	  input: AcceptInvitationTokenInput,
120	): Promise<Member> {
121	  const invitation = requireFound(
122	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
123	    "Invitation",
124	    "token",
125	  );
126	
127	  if (invitation.revokedAt !== null) {
128	    throw new Error("That invitation has been revoked");
129	  }
130	  if (invitation.acceptedAt !== null) {
131	    throw new Error("That invitation has already been accepted");
132	  }
133	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
134	    throw new Error("That invitation has expired");
135	  }
136	
137	  const existing = await memberRepo.findMember(invitation.orgId, userId);
138	  if (existing) return existing;
139	
140	  const member = await memberRepo.insertMember(
141	    invitation.orgId,
142	    userId,
143	    invitation.role,
144	    invitation.invitedBy,
145	  );
146	
147	  await invitationRepo.markInvitationAccepted(
148	    invitation.orgId,
149	    invitation.id,
150	    toIsoTimestamp(new Date()),
151	  );
152	
153	  await emit("member.joined", {
154	    ...envelope(invitation.orgId, userId),
155	    memberId: member.id,
156	    userId,
157	    role: member.role,
158	  });
159	
160	  return member;
161	}
