403	/** Cursor-paged member list joined with the user record the UI renders. */
404	export async function listMembers(
405	  input: ListMembersInput,
406	): Promise<Page<MemberWithUser>> {
407	  const db = getDb();
408	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
409	
410	  const filters = compact(
411	    orgPredicate(members.orgId, input.orgId),
412	    liveMemberPredicate(),
413	    input.role === undefined ? undefined : eq(members.role, input.role),
414	    input.status === undefined ? undefined : eq(members.status, input.status),
415	    input.query === undefined
416	      ? undefined
417	      : or(
418	          like(users.name, `%${input.query}%`),
419	          like(users.email, `%${input.query}%`),
420	        ),
421	  );
422	
423	  const total = db
424	    .select({ value: count() })
425	    .from(members)
426	    .innerJoin(users, eq(users.id, members.userId))
427	    .where(and(...filters))
428	    .get();
429	
430	  const rows = db
431	    .select({ member: members, user: users })
432	    .from(members)
433	    .innerJoin(users, eq(users.id, members.userId))
434	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
435	    .orderBy(desc(members.createdAt), desc(members.id))
436	    .limit(probeLimit(input.limit))
437	    .all();
438	
439	  return toPage(
440	    rows,
441	    input.limit,
442	    total?.value ?? 0,
443	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
444	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
445	  );
446	}
