374	export async function listNotifications(
375	  input: ListNotificationsInput,
376	): Promise<Page<Notification>> {
377	  const db = getDb();
378	  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };
379	
380	  const filters = compact(
381	    orgPredicate(notifications.orgId, input.orgId),
382	    eq(notifications.recipientId, input.recipientId),
383	    input.unreadOnly ? isNull(notifications.readAt) : undefined,
384	    input.kind === undefined || input.kind.length === 0
385	      ? undefined
386	      : inArray(notifications.kind, [...input.kind]),
387	  );
388	
389	  const total = db
390	    .select({ value: count() })
391	    .from(notifications)
392	    .where(and(...filters))
393	    .get();
394	
395	  const rows = db
396	    .select()
397	    .from(notifications)
398	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
399	    .orderBy(desc(notifications.createdAt), desc(notifications.id))
400	    .limit(probeLimit(input.limit))
401	    .all();
402	
403	  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({
404	    id: row.id,
405	    sortValue: row.createdAt,
406	  }));
407	}
