963	 * One pass per scheduler tick. Each org is only processed during the UTC hour
964	 * it configured, so a tick that runs every few minutes still sends exactly one
965	 * digest per day per recipient.
966	 */
967	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
968	  return runJob("digest-email", async (result) => {
969	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
970	
971	    for (const orgId of orgIds) {
972	      const org = await orgRepo.findOrgById(orgId);
973	      if (!org || !shouldRunForOrg(org, now)) continue;
974	
975	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
976	
977	      const windowEnd = toIsoTimestamp(now);
978	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
979	
980	      for (const recipientId of await listDigestRecipients(orgId)) {
981	        try {
982	          const bundle = await buildDigest(
983	            orgId,
984	            recipientId,
985	            windowStart,
986	            windowEnd,
987	          );
988	          if (!bundle) continue;
989	
990	          const recipient = await userRepo.findUserById(recipientId);
991	          if (!recipient) continue;
992	
993	          const rendered = await renderDigest(bundle, recipient);
994	          await sendEmail({ to: recipient.email, ...rendered });
995	
996	          // Once digested, these notifications are no longer "unread" — this
997	          // is what keeps a later run inside the same window from sending
998	          // the same digest twice.
999	          for (const entry of bundle.entries) {
1000	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
1001	          }
1002	
1003	          result.processed += 1;
1004	        } catch (error) {
1005	          result.failed += 1;
1006	          logger.error("digest failed", {
1007	            orgId,
1008	            recipientId,
1009	            reason: error instanceof Error ? error.message : String(error),
1010	          });
