1019	 * decision is worth testing on its own, without a database.
1020	 */
1021	export function shouldRunForOrg(org: Organization, now: Date): boolean {
1022	  if (org.archivedAt !== null) return false;
1023	  return now.getUTCHours() === org.settings.digestHourUtc;
1024	}
1025	import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
