1030	 *
1031	 * Issues, projects and comments are never physically removed — they get an
1032	 * `archived_at` timestamp. Repositories must express "live rows only" through
1033	 * these helpers so the predicate stays in one place; a raw
1034	 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
1035	 * drift this module prevents.
1036	 */
1037	
1038	export function isArchived(row: SoftDeletable): boolean {
1039	  return row.archivedAt !== null;
1040	}
1041	
1042	export function isLive(row: SoftDeletable): boolean {
1043	  return row.archivedAt === null;
1044	}
1045	
1046	/** Filters an in-memory collection according to an `ArchiveScope`. */
1047	export function applyArchiveScope<T extends SoftDeletable>(
1048	  rows: readonly T[],
1049	  scope: ArchiveScope = {},
1050	): readonly T[] {
1051	  return scope.includeArchived === true ? rows : rows.filter(isLive);
1052	}
1053	
1054	/** True when the repository should add the `archived_at IS NULL` predicate. */
1055	export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
1056	  return scope.includeArchived !== true;
1057	}
1058	
1059	/** The column patch that archives a row. */
1060	export function archivePatch(now: Date = new Date()): {
1061	  archivedAt: IsoTimestamp;
1062	  updatedAt: IsoTimestamp;
1063	} {
1064	  const stamp = toIsoTimestamp(now);
1065	  return { archivedAt: stamp, updatedAt: stamp };
1066	}
1067	
1068	/** The column patch that restores an archived row. */
1069	export function restorePatch(now: Date = new Date()): {
1070	  archivedAt: null;
1071	  updatedAt: IsoTimestamp;
1072	} {
1073	  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
1074	}
1075	
1076	export class AlreadyArchivedError extends Error {
1077	  readonly code = "conflict" as const;
1078	
1079	  constructor(readonly entity: string, readonly id: string) {
1080	    super(`${entity} ${id} is already archived.`);
1081	    this.name = "AlreadyArchivedError";
1082	  }
1083	}
1084	
1085	/** Guard for archive actions, so double-archiving is a domain-level conflict. */
1086	export function assertNotArchived(
1087	  entity: string,
1088	  id: string,
1089	  row: SoftDeletable,
1090	): void {
1091	  if (isArchived(row)) {
1092	    throw new AlreadyArchivedError(entity, id);
1093	  }
1094	}
