428	/** Truncates every table, keeping the schema — cheaper than re-migrating. */
429	export async function resetTestDb(): Promise<void> {
430	  if (!migrated) await setupTestDb();
431	
432	  const db = getDb();
433	  const tables = db.$client
434	    .prepare(
435	      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
436	    )
437	    .all() as readonly { name: string }[];
438	
439	  db.$client.pragma("foreign_keys = OFF");
440	  for (const table of tables) {
441	    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
442	  }
443	  db.$client.pragma("foreign_keys = ON");
444	}
