body=r'''/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite. Every
 * check runs before the first row is written, so a refused batch creates no
 * invitation at all.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  await chargeRateLimit(input.orgId, input.invites.length);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const seen = new Set<string>();
  for (const invite of input.invites) {
    const key = invite.email.toLowerCase();
    if (seen.has(key)) {
      throw new Error(`${invite.email} is listed more than once`);
    }
    seen.add(key);
  }

  for (const invite of input.invites) {
    await assertInvitable(input.orgId, invite.email, null);
  }

  await assertSeatsAvailable(org, input.invites.length);

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    invitations.push(
      await issueInvitation(actor, input.orgId, invite.email, invite.role),
    );
  }

  return invitations;
}

async function chargeRateLimit(orgId: OrgId, cost: number): Promise<void> {
  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, cost);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }
}

/**
 * An address may be invited unless it belongs to a current member or already
 * has a pending invitation (other than `replacing`, the one being re-sent).
 * Former members and addresses whose invitation lapsed are fine.
 */
async function assertInvitable(
  orgId: OrgId,
  email: string,
  replacing: InvitationId | null,
): Promise<void> {
  if (await memberRepo.findMemberByEmail(orgId, email)) {
    throw new Error(`${email} is already a member of this organization`);
  }

  const pending = await invitationRepo.findPendingInvitationByEmail(
    orgId,
    email,
  );
  if (pending && pending.id !== replacing) {
    throw new Error(`${email} already has a pending invitation`);
  }
}

/** Seats in use are the current members plus the pending invitations. */
async function assertSeatsAvailable(
  org: Organization,
  requested: number,
): Promise<void> {
  if (requested <= 0) return;

  const seatsUsed =
    (await memberRepo.countActiveMembers(org.id)) +
    (await invitationRepo.countPendingInvitations(org.id));

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, requested)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }
}

async function issueInvitation(
  actor: Actor,
  orgId: OrgId,
  email: string,
  role: Invitation["role"],
): Promise<Invitation> {
  const token = randomToken(32);
  const invitation = await invitationRepo.insertInvitation(
    orgId,
    {
      orgId,
      email,
      role: role as InviteMemberInput["role"],
      expiresInDays: DEFAULT_EXPIRY_DAYS,
    },
    actor.userId,
    hashToken(token),
  );

  await emit("member.invited", {
    orgId,
    actorId: actor.userId,
    occurredAt: invitation.createdAt,
    email,
    role,
  });

  return invitation;
}

/**
 * Accepting has no `Actor` to scope against — the person is not a member yet —
 * so every check comes off the stored row: the token must be pending, the org
 * must still exist, and the signed-in account must be the one invited.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That invitation is for an organization that no longer exists");
  }

  const user = await userRepo.findUserById(userId);
  if (!user || user.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("That invitation was sent to a different email address");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMemberIncludingRemoved(
    invitation.orgId,
    userId,
  );

  // The invitation is used up before the membership is written, so a link can
  // never be redeemed twice.
  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  // Already a current member: nothing to create and nobody new to announce.
  if (existing && existing.archivedAt === null) return existing;

  const member = existing
    ? await memberRepo.restoreMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing mints a new row: the original is revoked and replaced so the
 * audit trail keeps both, and the old link stops working immediately. The
 * replacement goes to the same address with the same role and a fresh
 * validity window. An expired invitation can be re-sent — that is the usual
 * reason to — but then it needs a free seat again, since it stopped holding
 * one when it expired.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (previous.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }

  const org = requireFound(
    await orgRepo.findOrgById(actor.orgId),
    "Organization",
    actor.orgId,
  );

  await chargeRateLimit(actor.orgId, 1);
  await assertInvitable(actor.orgId, previous.email, previous.id);

  const stillHoldsSeat = previous.expiresAt > toIsoTimestamp(new Date());
  await assertSeatsAvailable(org, stillHoldsSeat ? 0 : 1);

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return issueInvitation(actor, actor.orgId, previous.email, previous.role);
}
